      writeValue(buffer, value.encode());
    } else if (value is RecoverableItem) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    } else if (value is ScanProgress) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    } else if (value is RestoreOutcome) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    } else if (value is RecoverySummary) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    } else if (value is BackgroundScanState) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        return RecoveryAccess.decode(readValue(buffer)!);
      case 130:
        return RecoverySource.decode(readValue(buffer)!);
      case 131:
        return RecoverableItem.decode(readValue(buffer)!);
      case 132:
        return ScanProgress.decode(readValue(buffer)!);
      case 133:
        return RestoreOutcome.decode(readValue(buffer)!);
      case 134:
        return RecoverySummary.decode(readValue(buffer)!);
      case 135:
        return BackgroundScanState.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

